SET DEFINE OFF;
SET ECHO ON;
SET SERVEROUTPUT ON SIZE UNLIMITED;

PROMPT >>> [1/5] Initsialiseerin DEVHUB kasutaja ja õigused...

DECLARE
  v_count NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_count FROM all_users WHERE username = 'DEVHUB';
  IF v_count = 0 THEN
    -- Zero-Trust Rule 5: generate cryptographically secure random password and lock direct logins.
    -- DEVHUB operates as an internal backend engine schema accessed via APEX workspace schema association.
    EXECUTE IMMEDIATE 'CREATE USER DEVHUB IDENTIFIED BY "' || DBMS_RANDOM.STRING('X', 30) || 'aA1#" DEFAULT TABLESPACE USERS TEMPORARY TABLESPACE TEMP ACCOUNT LOCK';
  END IF;
  EXECUTE IMMEDIATE 'ALTER USER DEVHUB QUOTA UNLIMITED ON USERS';
  EXECUTE IMMEDIATE 'GRANT CREATE SESSION, CREATE TABLE, CREATE VIEW, CREATE PROCEDURE, CREATE SEQUENCE, CREATE JOB TO DEVHUB';
  BEGIN
    EXECUTE IMMEDIATE 'GRANT DB_DEVELOPER_ROLE TO DEVHUB';
  EXCEPTION
    WHEN OTHERS THEN NULL;
  END;
  BEGIN
    EXECUTE IMMEDIATE 'GRANT EXECUTE ON UTL_HTTP TO DEVHUB';
    EXECUTE IMMEDIATE 'GRANT EXECUTE ON UTL_URL TO DEVHUB';
  EXCEPTION
    WHEN OTHERS THEN NULL;
  END;
END;
/

-- Seome DEVHUB skeemi APEX töölauaga PROXY_WORKSPACE
  BEGIN
    EXECUTE IMMEDIATE 'BEGIN APEX_260100.APEX_INSTANCE_ADMIN.ADD_SCHEMA(p_workspace => ''PROXY_WORKSPACE'', p_schema => ''DEVHUB''); END;';
  EXCEPTION
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('Workspace add_schema märkus: ' || SQLERRM);
  END;
/

PROMPT >>> [2/5] Seadistan Host ACE väljundvõrgu õigused lokaalsete portide jaoks (8080-9502)...

BEGIN
  -- Security Hardening: strictly scope ACE to local services (localhost, 127.0.0.1, app-ords)
  -- Wildcard '*' is prohibited to prevent SSRF vulnerabilities.
  FOR h IN (SELECT 'localhost' AS host FROM dual UNION ALL SELECT '127.0.0.1' AS host FROM dual UNION ALL SELECT 'app-ords' AS host FROM dual) LOOP
    BEGIN
      DBMS_NETWORK_ACL_ADMIN.APPEND_HOST_ACE(
        host       => h.host,
        lower_port => 8080,
        upper_port => 9502,
        ace        => xs$ace_type(privilege_list => xs$name_list('http', 'connect'),
                                  principal_name => 'DEVHUB',
                                  principal_type => xs_acl.ptype_db)
      );
    EXCEPTION
      WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Host ACE märkus (' || h.host || '): ' || SQLERRM);
    END;
  END LOOP;
END;
/

