-- 1. DEVHUB_CONFIG
DECLARE
  v_count NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_count FROM all_tables WHERE owner = 'DEVHUB' AND table_name = 'DEVHUB_CONFIG';
  IF v_count = 0 THEN
    EXECUTE IMMEDIATE '
      CREATE TABLE DEVHUB.DEVHUB_CONFIG (
        CONFIG_KEY   VARCHAR2(50)  PRIMARY KEY,
        CONFIG_VALUE VARCHAR2(200),
        DESCRIPTION  VARCHAR2(400)
      )';
  END IF;
END;
/

-- 2. DEVHUB_SERVICES
DECLARE
  v_count NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_count FROM all_tables WHERE owner = 'DEVHUB' AND table_name = 'DEVHUB_SERVICES';
  IF v_count = 0 THEN
    EXECUTE IMMEDIATE '
      CREATE TABLE DEVHUB.DEVHUB_SERVICES (
        SERVICE_ID        VARCHAR2(50)  PRIMARY KEY,
        SERVICE_NAME      VARCHAR2(100) NOT NULL,
        CATEGORY          VARCHAR2(50)  DEFAULT ''MIDDLEWARE'',
        EXTERNAL_PORT     NUMBER,
        TARGET_URL        VARCHAR2(500),
        HEALTH_URL        VARCHAR2(500),
        WALLET_ALIAS      VARCHAR2(100),
        DEFAULT_USER      VARCHAR2(100),
        ICON_CLASS        VARCHAR2(100) DEFAULT ''fa-server'',
        SORT_ORDER        NUMBER        DEFAULT 10,
        IS_ACTIVE         VARCHAR2(1)   DEFAULT ''Y'',
        LAST_STATUS       VARCHAR2(20)  DEFAULT ''UNKNOWN'',
        LAST_CHECKED      TIMESTAMP WITH TIME ZONE,
        RESPONSE_TIME_MS  NUMBER,
        HTTP_STATUS_CODE  NUMBER
      )';
  END IF;
END;
/

