        l_html := l_html || '<div style="display:inline-block; padding: 4px 12px; background: rgba(59, 130, 246, 0.1); color: #2563eb; font-weight: 700; font-size: 0.8rem; border-radius: 9999px; margin-bottom: 12px;">🚀 SKAIDRĖ 9 / 9 • TOLIMESNI ŽINGSNIAI</div><h2 style="font-size: 1.8rem; font-weight: 800; margin-top: 0; margin-bottom: 8px; color: var(--theme-text, #0f172a);">Kaip Pradėti Nedelsiant?</h2><p style="font-size: 1.1rem; color: #64748b; margin-bottom: 24px;">Viskas automatizuota ir paleidžiama viena komanda terminale.</p><div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 16px; margin-bottom: 24px;"><div style="padding: 16px; border-radius: 8px; background: rgba(59,130,246,0.04); border: 1px solid rgba(59,130,246,0.15);"><div style="font-size: 1.4rem; margin-bottom: 6px;">📌</div><h4 style="margin: 0 0 6px 0; font-weight: 700; color: #2563eb;">1. Paleisti Aplinką</h4><p style="margin: 0; font-size: 0.88rem; color: #64748b; line-height: 1.5;">Įdiegti duomenų bazę ir paslaugas:<br/><code style=''color:#38bdf8;''>./scripts/setup-all.sh</code></p></div><div style="padding: 16px; border-radius: 8px; background: rgba(59,130,246,0.04); border: 1px solid rgba(59,130,246,0.15);"><div style="font-size: 1.4rem; margin-bottom: 6px;">📌</div><h4 style="margin: 0 0 6px 0; font-weight: 700; color: #2563eb;">2. Pasirinkti Brėžinį</h4><p style="margin: 0; font-size: 0.88rem; color: #64748b; line-height: 1.5;">Pakeisti architektūros profilį:<br/><code style=''color:#38bdf8;''>./scripts/module-toggle.sh</code></p></div><div style="padding: 16px; border-radius: 8px; background: rgba(59,130,246,0.04); border: 1px solid rgba(59,130,246,0.15);"><div style="font-size: 1.4rem; margin-bottom: 6px;">📌</div><h4 style="margin: 0 0 6px 0; font-weight: 700; color: #2563eb;">3. Paleisti Testus</h4><p style="margin: 0; font-size: 0.88rem; color: #64748b; line-height: 1.5;">Visiškai automatizuotas testavimas:<br/><code style=''color:#38bdf8;''>./scripts/test-apex-suite.sh</code></p></div></div><div style="padding-top: 16px; border-top: 1px solid #e2e8f0; display: flex; gap: 12px; align-items: center; flex-wrap: wrap;"><span style="font-size: 0.85rem; font-weight: 600; color: #64748b;">Nuorodos:</span><a href="f?p=' || V('APP_ID') || ':1:' || V('APP_SESSION') || '" class="t-Button t-Button--simple t-Button--small">🌐 Paslaugos</a><a href="f?p=' || V('APP_ID') || ':3:' || V('APP_SESSION') || '" class="t-Button t-Button--simple t-Button--small">📋 Brėžiniai</a><a href="f?p=' || V('APP_ID') || ':4:' || V('APP_SESSION') || '" class="t-Button t-Button--simple t-Button--small">📖 Dokumentacija</a></div>';
      ELSE /* et */
        l_html := l_html || '<div style="display:inline-block; padding: 4px 12px; background: rgba(59, 130, 246, 0.1); color: #2563eb; font-weight: 700; font-size: 0.8rem; border-radius: 9999px; margin-bottom: 12px;">🚀 SLAID 9 / 9 • JÄRGMISED SAMMUD</div><h2 style="font-size: 1.8rem; font-weight: 800; margin-top: 0; margin-bottom: 8px; color: var(--theme-text, #0f172a);">Kuidas Kohe Alustada?</h2><p style="font-size: 1.1rem; color: #64748b; margin-bottom: 24px;">Kõik vajalik on automatiseeritud ja koheselt käsurealt käivitatav.</p><div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 16px; margin-bottom: 24px;"><div style="padding: 16px; border-radius: 8px; background: rgba(59,130,246,0.04); border: 1px solid rgba(59,130,246,0.15);"><div style="font-size: 1.4rem; margin-bottom: 6px;">📌</div><h4 style="margin: 0 0 6px 0; font-weight: 700; color: #2563eb;">1. Käivita Keskkond</h4><p style="margin: 0; font-size: 0.88rem; color: #64748b; line-height: 1.5;">Paigalda andmebaas ja teenused:<br/><code style=''color:#38bdf8;''>./scripts/setup-all.sh</code></p></div><div style="padding: 16px; border-radius: 8px; background: rgba(59,130,246,0.04); border: 1px solid rgba(59,130,246,0.15);"><div style="font-size: 1.4rem; margin-bottom: 6px;">📌</div><h4 style="margin: 0 0 6px 0; font-weight: 700; color: #2563eb;">2. Vali Blueprint</h4><p style="margin: 0; font-size: 0.88rem; color: #64748b; line-height: 1.5;">Vali sobiv arhitektuuripinu:<br/><code style=''color:#38bdf8;''>./scripts/module-toggle.sh</code></p></div><div style="padding: 16px; border-radius: 8px; background: rgba(59,130,246,0.04); border: 1px solid rgba(59,130,246,0.15);"><div style="font-size: 1.4rem; margin-bottom: 6px;">📌</div><h4 style="margin: 0 0 6px 0; font-weight: 700; color: #2563eb;">3. Käivita Testid</h4><p style="margin: 0; font-size: 0.88rem; color: #64748b; line-height: 1.5;">Täisautomaatne testimine:<br/><code style=''color:#38bdf8;''>./scripts/test-apex-suite.sh</code></p></div></div><div style="padding-top: 16px; border-top: 1px solid #e2e8f0; display: flex; gap: 12px; align-items: center; flex-wrap: wrap;"><span style="font-size: 0.85rem; font-weight: 600; color: #64748b;">Kiirviited:</span><a href="f?p=' || V('APP_ID') || ':1:' || V('APP_SESSION') || '" class="t-Button t-Button--simple t-Button--small">🌐 Live Teenused</a><a href="f?p=' || V('APP_ID') || ':3:' || V('APP_SESSION') || '" class="t-Button t-Button--simple t-Button--small">📋 Blueprints</a><a href="f?p=' || V('APP_ID') || ':4:' || V('APP_SESSION') || '" class="t-Button t-Button--simple t-Button--small">📖 Dokumentatsioon</a></div>';
      END IF;
    END IF;

    l_html := l_html || '</div>';
    RETURN l_html;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN '<div class="t-Alert t-Alert--danger"><div class="t-Alert-content">' ||
             '<strong>Viga slaidi renderdamisel:</strong> ' || HTF.ESCAPE_SC(SQLERRM) ||
             '</div></div>';
  END get_slide_html;

END DEV_HUB_PKG;
/

-- 8. DEVHUB_PORT_CONFLICTS_V
CREATE OR REPLACE VIEW DEVHUB.DEVHUB_PORT_CONFLICTS_V AS
SELECT jt.module_key,
       jt.container_name,
       jt.configured_port,
       jt.conflicting_container,
       jt.recommended_port,
       jt.message,
       jt.has_conflict
  FROM (
    SELECT DEVHUB.DEV_HUB_PKG.get_port_conflicts_json() AS json_clob FROM dual
  ) v,
  JSON_TABLE(v.json_clob, '$.conflicts.*'
    COLUMNS (
      module_key            VARCHAR2(50)  PATH '$.module',
      container_name        VARCHAR2(100) PATH '$.container',
      configured_port       NUMBER        PATH '$.configured_port',
      conflicting_container VARCHAR2(100) PATH '$.conflicting_container',
      recommended_port      NUMBER        PATH '$.recommended_port',
      message               VARCHAR2(400) PATH '$.message',
      has_conflict          VARCHAR2(10)  PATH '$.has_conflict'
    )
  ) jt
 WHERE jt.has_conflict = 'true';
/

PROMPT >>> [5/5] Initsialiseerin vaikimisi konfiguratsiooni...

MERGE INTO DEVHUB.DEVHUB_CONFIG t
USING (
  SELECT 'IS_DEV_ENV' AS k, 'Y' AS v, 'Lokaalne arenduskeskkond' AS d FROM dual UNION ALL
  SELECT 'BRIDGE_URL' AS k, 'http://host.containers.internal:8089' AS v, 'Dev Hub Bridge REST otspunkt' AS d FROM dual
) s ON (t.CONFIG_KEY = s.k)
WHEN MATCHED THEN UPDATE SET t.CONFIG_VALUE = s.v
WHEN NOT MATCHED THEN INSERT (CONFIG_KEY, CONFIG_VALUE, DESCRIPTION) VALUES (s.k, s.v, s.d);

COMMIT;

PROMPT >>> ✅ DEVHUB skeemi ja paketi initsialiseerimine edukalt lõpetatud!
